// Read content_queue.json from the repo and return pending entries
const fs = require('fs');
const path = 'C:/Users/nev3s/repos/meaicon-website/content_queue.json';

try {
  const queue = JSON.parse(fs.readFileSync(path, 'utf8'));
  const pending = queue.filter(e => e.status === 'pending');

  if (pending.length === 0) {
    return [{ json: { empty: true, message: 'No pending entries in content_queue.json' } }];
  }

  // Sort by priority (descending)
  pending.sort((a, b) => (b.priority || 5) - (a.priority || 5));

  return pending.map(entry => ({
    json: {
      slug: entry.slug,
      title: entry.title,
      description: entry.description,
      section: entry.section,
      source_url: entry.source_url || '',
      competitors: entry.competitors || [],
      priority: entry.priority || 5,
      status: entry.status,
      attempts: entry.attempts || 0,
      max_attempts: entry.max_attempts || 3
    }
  }));
} catch (e) {
  return [{ json: { error: 'Failed to read content_queue.json: ' + e.message } }];
}

