// Parse critic response and decide path
const rawContent = $json.choices[0].message.content;
let verdict = 'REJECTED';
let qualityScore = 0;
let issues = [];
let suggestions = [];

try {
  const jsonMatch = rawContent.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    const parsed = JSON.parse(jsonMatch[0]);
    verdict = parsed.verdict || 'REJECTED';
    qualityScore = parsed.quality_score || 0;
    issues = parsed.issues || [];
    suggestions = parsed.suggestions || [];
  }
} catch (e) {
  verdict = 'REJECTED';
  issues = ['Critic response parse error: ' + e.message];
}

return [{
  json: {
    slug: $('Read Queue').first().json.slug,
    verdict: verdict,
    quality_score: qualityScore,
    issues: issues,
    suggestions: suggestions,
    enhanced_content: $('LangChain Enhance').first().json.choices[0].message.content,
    timestamp: new Date().toISOString()
  }
}];

