// Write enhanced content to the langchain output dir and update queue
const fs = require('fs');
const path = require('path');

const slug = $('Parse Critic Verdict').first().json.slug;
const topic = slug.split('/').pop();

const content = $('Self-Correct').first().json.choices[0].message.content || $('LangChain Enhance').first().json.choices[0].message.content;

const outputDir = path.join('C:/Users/nev3s/repos/meaicon-website/research-data/langchain', topic);
fs.mkdirSync(outputDir, { recursive: true });

// Write enhanced content
fs.writeFileSync(path.join(outputDir, 'enhanced-content.md'), content, 'utf8');

// Write critic feedback
const criticData = $('Parse Critic Verdict').first().json;
fs.writeFileSync(path.join(outputDir, 'critic-feedback.json'), JSON.stringify({
  topic: topic,
  verdict: 'SELF_CORRECTED',
  quality_score: criticData.quality_score,
  issues: criticData.issues,
  suggestions: criticData.suggestions,
  timestamp: new Date().toISOString()
}, null, 2), 'utf8');

return [{ json: { slug: slug, status: 'enhanced', content_written: true } }];

