// Log failure and update queue
const fs = require('fs');
const queuePath = 'C:/Users/nev3s/repos/meaicon-website/content_queue.json';
const queue = JSON.parse(fs.readFileSync(queuePath, 'utf8'));

const slug = $('Parse Critic Verdict').first().json.slug;
const criticData = $('Parse Critic Verdict').first().json;

const updated = queue.map(entry => {
  if (entry.slug === slug) {
    const attempts = (entry.attempts || 0) + 1;
    return {
      ...entry,
      status: attempts >= (entry.max_attempts || 3) ? 'failed' : 'pending',
      attempts: attempts,
      error: 'Critic rejected: ' + criticData.issues.join('; ')
    };
  }
  return entry;
});

fs.writeFileSync(queuePath, JSON.stringify(updated, null, 2), 'utf8');

return [{ json: { slug: slug, status: 'retry-queued', attempts: updated.find(e => e.slug === slug).attempts } }];
